[tool: web_search] {
  "results": [
    {
      "title": "Cost of Living Index - BestPlaces",
      "url": "https://www.bestplaces.net/cost-of-living/",
      "snippet": "BestPlaces' Cost of Living Index uses a U.S. average of 100 as the baseline for comparing housing, groceries, transportation, health care and utilities. The page notes that an index of 120 means costs are 20% above the national average, while 80 means costs are 20% below it.",
      "domain": "bestplaces.net",
      "rank": 1
    },
    {
      "title": "How the Cost of Living Index Is Calculated | BestPlaces",
      "url": "https://www.bestplaces.net/cost-of-living/methodology/",
      "snippet": "BestPlaces explains that its cost of living index is built from category weights for housing, groceries, transportation, health care and utilities, with the national average set to 100. The methodology page also states that housing carries the largest weight because it typically represents the biggest household expense.",
      "domain": "bestplaces.net",
      "rank": 2
    },
    {
      "title": "Methodology for Cost of Living Comparisons - BestPlaces",
      "url": "https://www.bestplaces.net/cost-of-living/methodology.aspx",
      "snippet": "According to BestPlaces, the index compares local prices to the U.S. average, where 100 equals the national benchmark. The site says the figures are updated regularly using sources such as census and market data to estimate relative costs across metro areas and states.",
      "domain": "bestplaces.net",
      "rank": 3
    },
    {
      "title": "BestPlaces Cost of Living Index FAQ",
      "url": "https://www.bestplaces.net/cost-of-living/faq/",
      "snippet": "BestPlaces says its cost of living index is designed so that the U.S. average equals 100, making scores above 100 more expensive and scores below 100 less expensive. An FAQ entry explains that a city with a cost of living index of 110 is about 10% more expensive than the U.S. average.",
      "domain": "bestplaces.net",
      "rank": 4
    },
    {
      "title": "Cost of Living Calculator and Index Methodology - BestPlaces",
      "url": "https://www.bestplaces.net/cost-of-living/calculator-methodology/",
      "snippet": "The BestPlaces methodology page describes how the calculator combines local prices and category weights to produce a single index with 100 as the U.S. average. It lists typical categories including housing, groceries, transportation and health care, and notes that regional differences in rent can have a large effect on the final score.",
      "domain": "bestplaces.net",
      "rank": 5
    }
  ],
  "query": "site:bestplaces.net cost of living index U.S. average 100 methodology",
  "count": 5
}

